const FIRSTNAME_MAX = 40;
const SUITE_SOURCE = "whatsapp-bot-backfill";
// Valores DCX (provider / interes). Ajustar si hace falta.
const DCX_INTEREST = 'No informado';
const DCX_FUENTE = 'Bot-Whatsapp';
const DCX_ORIGIN = 'Chatbot-Foton-Backfill';
const STOPWORDS = new Set(['de','del','la','el','un','una','los','las','que','mas','más','muy','yo','su','mi','me','y','o','en','con','por','para']);
const HINTS = [
  new RegExp('\\bmi\\s+nombre\\s+es\\s+([A-Za-zÁÉÍÓÚÜÑáéíóúüñ\']{2,20})', 'i'),
  new RegExp('\\bme\\s+llamo\\s+([A-Za-zÁÉÍÓÚÜÑáéíóúüñ\']{2,20})', 'i'),
  new RegExp('\\bsoy\\s+([A-Za-zÁÉÍÓÚÜÑáéíóúüñ\']{2,20})', 'i'),
];
const RE_SENTENCE = new RegExp('[?!@#:;]|https?://', 'i');
const RE_EVENT = new RegExp('^_event_', 'i');

function extractName(raw) {
  const t = String(raw || '').trim().replace(/\s+/g, ' ');
  if (!t) return null;
  if (RE_EVENT.test(t)) return null;
  const looksLikeSentence = RE_SENTENCE.test(t) || t.split(' ').length > 4;
  if (t.length <= FIRSTNAME_MAX && !looksLikeSentence) return t;
  for (const re of HINTS) {
    const m = t.match(re);
    if (m && m[1] && m[1].length >= 2 && !STOPWORDS.has(m[1].toLowerCase())) return m[1];
  }
  return null;
}

function splitName(full) {
  const parts = String(full || '').trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { firstName: 'Lead', lastName: 'WhatsApp' };
  if (parts.length === 1) return { firstName: parts[0], lastName: 'WhatsApp' };
  return { firstName: parts.slice(0, -1).join(' '), lastName: parts[parts.length - 1] };
}

const cleanPhone = (p) => String(p || '').replace(/^whatsapp:/i, '').replace(/^\+/, '').replace(/\s+/g, '');
const clamp = (v, n) => String(v == null ? '' : v).slice(0, n);
const nowIso = new Date().toISOString();

return LEADS.map((lead) => {
  const norm = (v) => { const s = String(v == null ? '' : v).trim(); return s || 'No informado'; };
  const usable = extractName(lead.name);
  const nombre = usable ? norm(usable) : 'No informado';
  const mail = norm(lead.mail);
  const vehiculo = norm(lead.producto);
  const realMail = Boolean(lead.mail) && String(lead.mail).includes('@');

  const resumen = [
    'Backfill CSV leads_no_cargados.',
    'Nombre: ' + nombre + '.',
    'Mail: ' + mail + '.',
    'Vehículo de interés: ' + vehiculo + '.',
    'Intentos previos del bot: ' + lead.intentos + '.',
    'Fecha de recuperación: ' + nowIso + '.',
  ].join(' ');
  const detalle = (usable && usable === lead.name)
    ? resumen
    : resumen + ' | Texto original enviado como nombre: ' + (String(lead.name || '').trim() || 'No informado');

  const suiteBody = {
    phone: cleanPhone(lead.tel),
    source: SUITE_SOURCE,
    first_name: nombre.slice(0, FIRSTNAME_MAX),
    interest_level: 'medium',
    notes: detalle,
    additional_data: {
      backfill: true,
      nombre: nombre,
      mail: mail,
      vehiculo_interes: vehiculo,
      intentos_previos: lead.intentos,
      close_reason: 'backfill_csv',
    },
  };
  if (realMail) suiteBody.email = String(lead.mail).trim();

  const nm = usable ? splitName(usable) : { firstName: 'No informado', lastName: 'No informado' };
  const phoneDcx = cleanPhone(lead.tel);

  // Esquema DCX/Toyota (igual que ../botayala/src/salesforce.js y hermanos del grupo).
  const dcxBody = {
    prospect: {
      requestdate: new Date().toISOString().split('T')[0],
      customer: {
        interest: DCX_INTEREST,
        productInterest: vehiculo,
        contacts: [
          {
            names: [
              { part: 'first', value: clamp(nm.firstName, FIRSTNAME_MAX) },
              { part: 'last', value: clamp(nm.lastName || 'No informado', 80) },
            ],
            phones: [{ type: 'mobile', value: phoneDcx }],
          },
        ],
        comments: clamp(detalle, 4000),
      },
      vehicles: [{ make: 'Foton', model: vehiculo }],
      provider: {
        name: { value: DCX_FUENTE, origin: DCX_ORIGIN },
      },
    },
  };
  if (realMail) dcxBody.prospect.customer.contacts[0].emails = [{ type: 'personal', value: String(lead.mail).trim() }];

  return { json: { tel: suiteBody.phone, nombre: nombre, mail: mail, vehiculo: vehiculo, suiteBody: suiteBody, dcxBody: dcxBody } };
});

// Resumen de la rama DCX (loop). El resultado de la Suite se ve en la salida
// del nodo 'Crear lead en Suite'.
const all = $input.all();
let ok = 0, fail = 0;
const errores = [];
for (const it of all) {
  const j = it.json || {};
  const failed = Boolean(j.error) || (j.statusCode && j.statusCode >= 400) || j.error === 'true';
  if (failed) { fail++; errores.push({ tel: j.tel || null, detalle: (j.error && (j.error.message || j.error)) || j.message || j.statusCode }); }
  else ok++;
}
return [{ json: { destino: 'DCX Toyota (loop)', total: all.length, ok, fail, errores } }];
